code.source:
#include <iostream>
using namespace std;

int main() {
    int a = 17, b = 5;
    cout << a + b << endl;
    cout << a - b << endl;
    cout << a * b << endl;
    cout << a / b << endl;
    cout << a % b << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int visitors = 10;
    visitors += 5;
    visitors++;
    cout << "Visitors: " << visitors << endl;
    double half = 7 / 2.0;
    cout << "Half: " << half << endl;
    return 0;
}

